-- Struct
select @ngay_ct as ngay_ct, @dien_giai as dien_giai, @ma_quyen as ma_nk, @ma_kh as ma_kh
		, @tk_no as tk_no, @tk_co as tk_co, @ma_vv as ma_vv, @tien_nt as tien_nt, @s2 as s2
		, @ma_hd as ma_hd, @id_tich_hop as ma_td6, @fcode4 as fcode4
		, @status as status, @ma_dvcs as ma_dvcs, @id_tich_hop as id_tich_hop
		, 1 as stt
	into #datatmp

declare @field varchar(64), @message nvarchar(512)
exec zrs_Posting$Post2GL$Checking 'BC1', @ma_dvcs, @ngay_ct, 1, @field out, @message out, @@language, @@userID, @@admin, '@@sysDatabaseName'
if isnull(@message, '') <> '' begin
	select @field as field, @message as message, '' as script
	return
end

exec dbo.zrs_createBC1$4giaodich @@sysDatabaseName, @@userID, 2

select '' as field, '' as message, 'on$&Identity;$QueryComplete(this);' as script
return







			&OutlineEntry;

function load$&Identity;$(f) {
	var g = f.grid;

	f.add_onResponseComplete(on$&Identity;$ResponseComplete);
	f._looking = f.getItem('ma_quyen')._controlBehavior;
	f._looking.add_loading(on$&Identity;$Before$Loading);
	f.setItemValues('ma_kh, ten_kh%l, ma_vv, ma_hd, ma_hd_goc, id_tich_hop, ma_nvbh, tien_nt', [g._ma_kh, g._ten_kh, g._ma_vv, g._ma_hd, g._ma_hd_goc, g._id_tich_hop, g._ma_nvbh, g._tien_nt]);

	f.request('ValueDefault', 'ValueDefault', ['ma_dvcs', 'ma_vv', 'ma_kh', 'ma_hd', 'id_tich_hop', 'ma_nvbh']);
	f.getItem('ngay_ct').focus();
	f.setReferenceKeyFilter('fcode4');
}
function dispose$&Identity;$(f) {
	try {f._looking.remove_loading(on$&Identity;$Before$Loading);} catch (ex) {}
	try {f.remove_onResponseComplete(on$&Identity;$ResponseComplete);} catch (ex) {}
}
function on$&Identity;$ResponseComplete(sender, e) {
	var f = e.object, context = e.type.Context, result = e.type.Result;
	switch (context) {
		case 'ValueDefault':
			f.setItemValues('ma_dvcs, ngay_ct, ma_quyen, ten_quyen%l, ten_hdl, ten_vv%l, ten_nvbh%l'
					, [result[0].Value, result[1].Value, result[2].Value, result[3].Value, result[4].Value, result[5].Value, result[6].Value]);
			f.setReferenceKeyFilter('fcode4');
			f.request('DateChange', 'DateChange', ['ma_dvcs', 'ngay_ct'], null);
			break;
		case 'BussinessCode':
					f.setItemValues('s2, tk_no, ten_tk_no%l, tk_co, ten_tk_co%l'
					, [result[2].Value, result[3].Value, result[4].Value, result[5].Value, result[6].Value]);
			break;
		case 'DateChange':
			f.setItemValues('ma_quyen, ten_quyen%l',[result[0].Value, result[1].Value]);
			break;
		default:
			break;
	}
}



function on$&Identity;$Before$Loading(sender, e) {
	var f = sender._element.parentForm;
	if (!f.validFields('ngay_ct')) e.type.cancelEvent = true;
	else {
		var g = f.grid;
		a = [
			{Name: 'd', Type: 'DateTime', Value: f.getItemValue('ngay_ct')},
			{Name: 'u', Type: 'String', Value: f.getItemValue('ma_dvcs')},
			{Name: 'c', Type: 'String', Value: 'BC1'}
		];
		sender.set_memvars(a);
	}
}
function on$&Identity;$QueryComplete(f) {
	var g = f.grid;
	g._formScript = 'show$&Identity;$QueryComplete(this)';
}
function onChange$&Identity;$Date(o) {
		var f = o.parentForm;
		if (!f.validFields('ngay_ct')) return;

		var a = [
				{Name: 'd', Type: 'DateTime', Value: f.getItemValue('ngay_ct')},
				{Name: 'u', Type: 'String', Value: f.getItemValue('ma_dvcs')},
				{Name: 'c', Type: 'String', Value: 'BC1'}
		];
		f._looking.set_memvars(a);

		f.setItemValues('ma_quyen, ten_quyen%l', ['', '']);
		f.request('DateChange', 'DateChange', ['ma_dvcs', 'ngay_ct'], null);
}

function show$&Identity;$QueryComplete(g) {
	var v = (g._language == 'v'), id = g.get_id();
	var e = (v ? 'Chương trình đã thực hiện xong.' : 'The process was completed successfully.');
	$message.show(e, String.format('$find(\'{0}\')._focusWhenTabChanged();', id));
	g._focusWhenTabChanged();
	g.goToPage(-1);
}
function onChange$&Identity;$BussinessCode(o) {
	var f = o.parentForm;
	f.request('BussinessCode', 'BussinessCode', ['ma_nghiep_vu'], o);
}

function onChange$&Identity;$Account(o){
	var f = o.parentForm;
	f.setReferenceKeyFilter('fcode4');
}









				declare @d smalldatetime = convert(char(8), getdate(), 112), @u varchar(33) = @ma_dvcs, @c varchar(3) = 'BC1'
								, @ten_vv nvarchar(256), @ten_hd nvarchar(256), @ten_nvbh nvarchar(256)

				select top 1 rtrim(ma_nk) as ma_quyen, rtrim(ten_nk%l) as ten_quyen%l into #q from v20dmnk where ((ma_dvcs = '') or (ma_dvcs = @u)) and ((@d >= ngay_hl_tu or ngay_hl_tu is null) and (@d <= ngay_hl_den or ngay_hl_den is null)) 
					and ma_nk in (select ma_nk from v20dmctnk where ma_ct = @c and (lstuser = '' or charindex(rtrim(@@userName) + ',', replace(lstuser, ' ', '') + ',') > 0)) and status = '1'

				if not exists(select 1 from #q) insert into #q select '', ''

				select @ten_vv = ten_vv from dmvv with(nolock) where ma_vv = @ma_vv
				select @ten_hd = ten_hd from dmhd with(nolock) where ma_hd = @ma_hd
				select @ten_nvbh = ten_nvbh from dmnvbh with(nolock) where ma_nvbh = @ma_nvbh

				--Tiền còn lại
				/*
				declare @tien_da_thu numeric(19,4), @tien_nt numeric(19,4)
				select @tien_da_thu = sum(tien) from _crdatcho where ma_dat_cho = @id_tich_hop 
				select @tien_nt = tong_tien - isnull(@tien_da_thu, 0) from dm_dat_cho where ma_dat_cho = @id_tich_hop
					*/
				select top 1 @@unit as ma_dvcs, @d as ngay_ct, a.*, @ten_vv as ten_vv, @ten_hd as ten_hd, @ten_nvbh--, @tien_nt as tien_nt 
						from #q a
				return






				declare @u varchar(33) = @ma_dvcs, @c varchar(3) = 'BC1', @d smalldatetime = @ngay_ct

				select top 1 rtrim(ma_nk) as ma_quyen, rtrim(ten_nk%l) as [ten_quyen%l]
				from v20dmnk 
				where ((ma_dvcs = '') or (ma_dvcs = @u)) 
					and ((@d >= ngay_hl_tu or ngay_hl_tu is null) and (@d <= ngay_hl_den or ngay_hl_den is null)) 
					and ma_nk in (
							select ma_nk from v20dmctnk 
							where ma_ct = @c 
								and (lstuser = '' or charindex(rtrim(@@userName) + ',', replace(lstuser, ' ', '') + ',') > 0)
					) 
					and status = '1'

				if @@rowcount = 0 select '' as ma_quyen, '' as [ten_quyen%l]
				return





	&OutlineCss;
